import{_ as t,o,c as i,a2 as a}from"./chunks/framework.DGk0zlJw.js";const g=JSON.parse('{"title":"Installation acceptance checklist (71 items · 2026-10-12)","description":"","frontmatter":{},"headers":[],"relativePath":"acceptance-checklist.md","filePath":"acceptance-checklist.md"}'),n={name:"acceptance-checklist.md"};function r(s,e,l,c,d,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="installation-acceptance-checklist-71-items-·-2026-10-12" tabindex="-1">Installation acceptance checklist (71 items · 2026-10-12) <a class="header-anchor" href="#installation-acceptance-checklist-71-items-·-2026-10-12" aria-label="Permalink to &quot;Installation acceptance checklist (71 items · 2026-10-12)&quot;">​</a></h1><blockquote><p>Source: the three ledgers in <code>docs/mvp-issues.md</code>「装机对照清单」(verified 1 + fixed-pending-verify 17 + not fixed 53 = <strong>71 items</strong>; 2026-10-12 eleventh re-sort corrected the original 51/68 sum drift; 批3-补47 added 2.17 and then line-by-line recount). This version expands each item into a three-part form: <strong>preconditions / verification steps / expected results</strong>. Every step can be followed as written and every item can be receipted individually. Items with local automation evidence annotate the corresponding unit tests under &quot;Appendix: local automation coverage notes&quot;; the real machine only supplies the UI/interaction half.</p></blockquote><h2 id="_0-general-preparation-referenced-by-number-by-each-item-not-repeated" tabindex="-1">0. General preparation (referenced by number by each item, not repeated) <a class="header-anchor" href="#_0-general-preparation-referenced-by-number-by-each-item-not-repeated" aria-label="Permalink to &quot;0. General preparation (referenced by number by each item, not repeated)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Number</th><th>Preparation</th></tr></thead><tbody><tr><td><strong>E0 install</strong></td><td>Download the latest green-run nightly assets from daily-build (zip + SHA256SUMS verified consistent), extract to a clean directory and run. <strong>Version gate</strong>: packages after 2026-10-12 (批3-补42 DSL, 批3-补45 floating widening, 批3-补47 update check landed after that) contain the new items; earlier packages cannot exercise them</td></tr><tr><td><strong>E1 logs</strong></td><td><code>%APPDATA%\\Beacon\\logs\\beacon-YYYYMMDD.log</code>; failing items attach log-line evidence</td></tr><tr><td><strong>E2 receipt</strong></td><td>Record each item as &quot;passed / failed + phenomenon + screenshot or log line&quot;; on pass, annotate the date on the corresponding line in <code>docs/mvp-issues.md</code>; on failure, record only the phenomenon, do not self-repair</td></tr><tr><td><strong>C-GH</strong></td><td>A GitHub connection (real PAT) + one <code>github.pull_requests</code> and one <code>github.actions.runs</code> widget (pointing at a real repository with PR and Actions activity)</td></tr><tr><td><strong>C-HTTP</strong></td><td>An http connection (any reachable JSON endpoint; a LAN packager or a public echo service both work)</td></tr><tr><td><strong>C-MACHINE</strong></td><td>A machine connection (zero credentials)</td></tr><tr><td><strong>C-HERALD</strong></td><td>A self-hosted herald instance connection (cuihairu/herald)</td></tr><tr><td><strong>C-MIMO</strong></td><td>A Xiaomi MiMo connection + browser login to platform.xiaomimimo.com as backup (get the Cookie via F12)</td></tr><tr><td><strong>C-JENKINS</strong></td><td>A Jenkins connection (the public anonymous instance <code>https://weekly.ci.jenkins.io</code> suffices, or self-hosted)</td></tr><tr><td><strong>C-MOONSHOT</strong></td><td>A Moonshot open platform Key (platform.moonshot.cn; not interchangeable with Kimi For Coding)</td></tr><tr><td><strong>C-DISCONNECT</strong></td><td>A way to cut the network: turn off Wi-Fi / unplug the cable; recovery the same</td></tr><tr><td><strong>C-DPI</strong></td><td>A 200%/250% scaled display (or change scaling in Windows Settings); with multiple monitors, at least two monitors at different scales</td></tr></tbody></table><p>Overall receipt criteria: MVP acceptance (B-803) closes once everything passes; archive recordings/screenshots under <code>docs/</code>.</p><hr><h2 id="_1-verified-1-item-archived-not-executed-again" tabindex="-1">1. Verified (1 item, archived, not executed again) <a class="header-anchor" href="#_1-verified-1-item-archived-not-executed-again" aria-label="Permalink to &quot;1. Verified (1 item, archived, not executed again)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Conclusion</th></tr></thead><tbody><tr><td>Floating transparency floor 0.4→0.2 (批3-补10/补13⑤)</td><td>User confirmed fixed on installation 2026-10-10; keep it as is</td></tr></tbody></table><hr><h2 id="_2-fixed-pending-verification-17-items-—-focus-on-these-with-the-latest-nightly" tabindex="-1">2. Fixed, pending verification (17 items — focus on these with the latest nightly) <a class="header-anchor" href="#_2-fixed-pending-verification-17-items-—-focus-on-these-with-the-latest-nightly" aria-label="Permalink to &quot;2. Fixed, pending verification (17 items — focus on these with the latest nightly)&quot;">​</a></h2><h3 id="_2-1-b-301-real-pat-connection-test-success-failure-paths" tabindex="-1">2.1 B-301 | Real PAT connection test success/failure paths <a class="header-anchor" href="#_2-1-b-301-real-pat-connection-test-success-failure-paths" aria-label="Permalink to &quot;2.1 B-301 | Real PAT connection test success/failure paths&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0, E2; one revocable real GitHub PAT.</li><li><strong>Steps</strong>: ① Settings → Connections → new GitHub, mistype the PAT by one character → &quot;Test connection&quot;; ② leave the PAT empty → &quot;Test connection&quot;; ③ enter the correct PAT → &quot;Test connection&quot;; ④ swap in a revoked PAT → &quot;Test connection&quot;.</li><li><strong>Expected</strong>: ①④ clearly report authentication failure (not &quot;connection normal&quot;); ② goes through an anonymous request and honestly shows the anonymous result (does not falsely report authenticated); ③ the connection is healthy and the rate-limit headers are observed.</li></ul><h3 id="_2-2-b-302-real-repository-pr-manual-verification-count-and-yellow-highlight" tabindex="-1">2.2 B-302 | Real repository PR manual verification (count and yellow highlight) <a class="header-anchor" href="#_2-2-b-302-real-repository-pr-manual-verification-count-and-yellow-highlight" aria-label="Permalink to &quot;2.2 B-302 | Real repository PR manual verification (count and yellow highlight)&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0, C-GH.</li><li><strong>Steps</strong>: ① add a <code>github.pull_requests</code> widget pointing at an active repository; ② compare the Open PR count with the GitHub web page; ③ refresh (tray Refresh All); ④ create a new PR or close a PR and refresh again.</li><li><strong>Expected</strong>: The count matches the web page; yellow while there are open PRs, green when it hits zero; additions/closures are reflected within ≤1 refresh cycle.</li></ul><h3 id="_2-3-b-302-real-repository-red-ci-criterion" tabindex="-1">2.3 B-302 | Real repository red CI criterion <a class="header-anchor" href="#_2-3-b-302-real-repository-red-ci-criterion" aria-label="Permalink to &quot;2.3 B-302 | Real repository red CI criterion&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: Same as 2.2, and the repository needs an open PR with red CI (or run a check red on some PR).</li><li><strong>Steps</strong>: ① observe the PR card summary; ② (optional) toggle the <code>warn_on_red_ci</code> switch and refresh to compare.</li><li><strong>Expected</strong>: The red-CI PR summary shows an &quot;N red ci&quot; section; after a 304 re-probe the terminal state is reused without another request; when the switch is off, red CI does not affect it.</li></ul><h3 id="_2-4-b-303-real-workflow-manual-verification-success-failure-running" tabindex="-1">2.4 B-303 | Real workflow manual verification (success/failure/running) <a class="header-anchor" href="#_2-4-b-303-real-workflow-manual-verification-success-failure-running" aria-label="Permalink to &quot;2.4 B-303 | Real workflow manual verification (success/failure/running)&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0, C-GH (a <code>github.actions.runs</code> widget).</li><li><strong>Steps</strong>: ① trigger one successful run, wait for it to finish and refresh; ② trigger one failing run; ③ trigger a long run (&gt;2 minutes) and refresh while it is running.</li><li><strong>Expected</strong>: Success→green, failure→red, running→yellow with increasing duration; a run stuck at the 16-minute level formats the duration correctly (no negatives / garbled text); a malformed JSON response is shown explicitly as Degraded without crashing.</li></ul><h3 id="_2-5-b-303-real-workflow-mapping-review" tabindex="-1">2.5 B-303 | Real workflow mapping review <a class="header-anchor" href="#_2-5-b-303-real-workflow-mapping-review" aria-label="Permalink to &quot;2.5 B-303 | Real workflow mapping review&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: Same as 2.4.</li><li><strong>Steps</strong>: Cross-check each Beacon card against the GitHub web run status one by one (queued/running/success/failure/cancelled).</li><li><strong>Expected</strong>: The state mapping corresponds one-to-one with the web page; cancelled is not misjudged as failure.</li></ul><h3 id="_2-6-批3-补8-xiaomi-console-conventions-glm-5h-primary-slot" tabindex="-1">2.6 批3-补8 | Xiaomi console conventions + GLM 5h primary slot <a class="header-anchor" href="#_2-6-批3-补8-xiaomi-console-conventions-glm-5h-primary-slot" aria-label="Permalink to &quot;2.6 批3-补8 | Xiaomi console conventions + GLM 5h primary slot&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0, C-MIMO; a GLM real-Key connection.</li><li><strong>Steps</strong>: ① record the MiMo console Cookie (F12 → Application → Cookies → paste the whole <code>api-platform_ph</code> line); ② refresh the MiMo card; ③ observe the GLM card&#39;s main value.</li><li><strong>Expected</strong>: MiMo shows plan used / total / percentage (data from the console API, not a &quot;no quota slot&quot; placeholder); GLM&#39;s main slot is the 5h rolling-window percentage.</li></ul><h3 id="_2-7-批3-补9-17-18-23-floating-progress-bar-quick-panel-bottom" tabindex="-1">2.7 批3-补9/17/18/23 | Floating progress bar + quick panel bottom <a class="header-anchor" href="#_2-7-批3-补9-17-18-23-floating-progress-bar-quick-panel-bottom" aria-label="Permalink to &quot;2.7 批3-补9/17/18/23 | Floating progress bar + quick panel bottom&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0; a numeric widget (e.g. GLM/bigmodel quota) with &quot;numeric floating window&quot; on.</li><li><strong>Steps</strong>: ① look at the floating tile progress-bar form; ② push usage to ≥80% (or adjust the threshold); ③ open the Quick Panel and look at the RECENT EVENTS section.</li><li><strong>Expected</strong>: The progress bar is a 4 DIP rounded bar + an &quot;NN% &quot; readout (default form); yellow at ≥80%, red when full; the &quot;pool water&quot; effect only appears when selected in settings; RECENT EVENTS scrolls inside the Grid and does not break the panel.</li></ul><h3 id="_2-8-批3-补11-ark-quota-exhausted-display" tabindex="-1">2.8 批3-补11 | Ark quota-exhausted display <a class="header-anchor" href="#_2-8-批3-补11-ark-quota-exhausted-display" aria-label="Permalink to &quot;2.8 批3-补11 | Ark quota-exhausted display&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0; an ark connection (Coding Plan). Natural exhaustion is hard to trigger, so you can temporarily drag the widget threshold very low to simulate the judgment.</li><li><strong>Steps</strong>: ① wait for some window (5h/weekly/monthly) to exhaust, or simulate it with the threshold; ② observe when a 429 AccountQuotaExceeded-class response arrives.</li><li><strong>Expected</strong>: The card shows &quot;额度用尽（窗名，重置时间）&quot; (quota exhausted (window name, reset time)); the 429 exhaustion special case is treated as that window spent with the reset time; an ordinary rate-limit 429 does not flip the state.</li></ul><h3 id="_2-9-批3-补12-notification-rule-wiring" tabindex="-1">2.9 批3-补12 | Notification rule wiring <a class="header-anchor" href="#_2-9-批3-补12-notification-rule-wiring" aria-label="Permalink to &quot;2.9 批3-补12 | Notification rule wiring&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0; add one custom rule under Settings → Notifications (e.g. Toast when some widget is Warning+).</li><li><strong>Steps</strong>: ① save the rule; ② manufacture a state that satisfies the condition (e.g. cut that connection or inject a failure); ③ change the rule and retest.</li><li><strong>Expected</strong>: The custom rule actually fires a Toast (before the wiring it was an empty promise); after modifying the rule the next evaluation takes effect, no restart needed.</li></ul><h3 id="_2-10-批3-补13-ui-ux-audit-6-groups-of-discoverability-fixes-5-transparency-verified" tabindex="-1">2.10 批3-补13 | UI/UX audit 6 groups of discoverability fixes (⑤ transparency verified) <a class="header-anchor" href="#_2-10-批3-补13-ui-ux-audit-6-groups-of-discoverability-fixes-5-transparency-verified" aria-label="Permalink to &quot;2.10 批3-补13 | UI/UX audit 6 groups of discoverability fixes (⑤ transparency verified)&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: Walk each group: ① the action standalone page is discoverable; ② the detail window scroll region is resident (does not rely on noticing a scrollbar); ③ the settings form is laid out compactly; ④ the refresh tiers have Chinese labels; ⑤ the L2 tile two-column layout; ⑥ screenshot the settings page for the archive.</li><li><strong>Expected</strong>: All groups match the designs recorded in 批3-补13; no buttons/regions with &quot;invisible&quot; problems.</li></ul><h3 id="_2-11-批3-补19-edge-collapsed-strip-cannot-be-recovered" tabindex="-1">2.11 批3-补19 | Edge-collapsed strip cannot be recovered <a class="header-anchor" href="#_2-11-批3-补19-edge-collapsed-strip-cannot-be-recovered" aria-label="Permalink to &quot;2.11 批3-补19 | Edge-collapsed strip cannot be recovered&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: ① drag the capsule / floating panel to a screen edge so it collapses to a strip; ② hover the strip with the mouse; ③ move away and hover again.</li><li><strong>Expected</strong>: Hovering the strip expands it back to the full panel (no more death loop / unrecoverable); the strip and the expanded panel share the same Place math, geometry does not jump.</li></ul><h3 id="_2-12-批3-补20-5k-high-scaling-clipped-text-dpi" tabindex="-1">2.12 批3-补20 | 5K / high scaling clipped text (DPI) <a class="header-anchor" href="#_2-12-批3-补20-5k-high-scaling-clipped-text-dpi" aria-label="Permalink to &quot;2.12 批3-补20 | 5K / high scaling clipped text (DPI)&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0, C-DPI (200%/250%).</li><li><strong>Steps</strong>: ① open the detail window at 200% scaling; ② look at the capsule and floating tile text; ③ repeat at 250%.</li><li><strong>Expected</strong>: The detail window sizes to content and text is complete, not clipped; the capsule / floating panel DIP layout is correct (the earlier 5K clipping root cause was not resizing and falling back to fixed physical pixels).</li></ul><h3 id="_2-13-批3-补20-drag-follow-the-cursor-cross-screen-flicker" tabindex="-1">2.13 批3-补20 | Drag follow-the-cursor + cross-screen flicker <a class="header-anchor" href="#_2-13-批3-补20-drag-follow-the-cursor-cross-screen-flicker" aria-label="Permalink to &quot;2.13 批3-补20 | Drag follow-the-cursor + cross-screen flicker&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0, multiple monitors (a high-refresh-rate mouse is better).</li><li><strong>Steps</strong>: ① drag the capsule slowly; ② fling it quickly; ③ drag across two monitors with different DPIs.</li><li><strong>Expected</strong>: Follows the cursor the whole way without crawling (the start-point absolute positioning fix removes per-event accumulation rounding); no re-layout flicker while dragging across DPIs (re-layout skips WM_DPICHANGED during a drag).</li></ul><h3 id="_2-14-批3-补21-moonshot-balance-card" tabindex="-1">2.14 批3-补21 | Moonshot balance card <a class="header-anchor" href="#_2-14-批3-补21-moonshot-balance-card" aria-label="Permalink to &quot;2.14 批3-补21 | Moonshot balance card&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0, C-MOONSHOT.</li><li><strong>Steps</strong>: ① create a Moonshot connection (platform.moonshot.cn Key) → test connection; ② add a <code>moonshot.balance</code> widget; ③ compare the balance with the web page; ④ raise <code>warn_below</code> above the current balance.</li><li><strong>Expected</strong>: The connection is healthy and the balance matches the web page; balance ≤ warn_below (default 20) turns yellow, ≤ error_below (default 5) turns red.</li></ul><h3 id="_2-15-批3-补22-drag-across-three-screens-follow-the-cursor" tabindex="-1">2.15 批3-补22 | Drag across three screens follow-the-cursor <a class="header-anchor" href="#_2-15-批3-补22-drag-across-three-screens-follow-the-cursor" aria-label="Permalink to &quot;2.15 批3-补22 | Drag across three screens follow-the-cursor&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0, three monitors at different scales (if no three-screen setup, approximate with two).</li><li><strong>Steps</strong>: Slowly drag the capsule across the three screens in turn, pausing on each to observe the size.</li><li><strong>Expected</strong>: The anchor always follows the cursor (physical-pixel convention); no scaling mismatch and no size jumps across different-scale screens.</li></ul><h3 id="_2-16-批3-补22-detail-window-still-clips-text-at-200" tabindex="-1">2.16 批3-补22 | Detail window still clips text at 200% <a class="header-anchor" href="#_2-16-批3-补22-detail-window-still-clips-text-at-200" aria-label="Permalink to &quot;2.16 批3-补22 | Detail window still clips text at 200%&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0, C-DPI (200%).</li><li><strong>Steps</strong>: Open any widget detail window at 200% scaling; check the title, body, and bottom button area.</li><li><strong>Expected</strong>: Complete display without clipping (Resize adds back the non-client difference: GetWindowRect−GetClientRect).</li></ul><h3 id="_2-17-批3-补47-update-check-three-lines-failure-degradation" tabindex="-1">2.17 批3-补47 | Update check three lines + failure degradation <a class="header-anchor" href="#_2-17-批3-补47-update-check-three-lines-failure-degradation" aria-label="Permalink to &quot;2.17 批3-补47 | Update check three lines + failure degradation&quot;">​</a></h3><ul><li><strong>Preconditions</strong>: E0 (a package after 2026-10-12), C-DISCONNECT (means to cut and restore the network).</li><li><strong>Steps</strong>: ① open Settings → About, click &quot;Check for updates&quot; and wait for a conclusion; ② cut the network and click &quot;Check for updates&quot; again; ③ restore the network and click again. When there is a new version, check that the &quot;Open download page&quot; button appears and points at releases/latest.</li><li><strong>Expected</strong>: ① the three lines are complete — current version / remote latest version (tag_name) / check result (already latest, or &quot;new version vN&quot; + &quot;Open download page&quot;), with the last check time updated to the minute; ② with the network cut it shows &quot;无法检查更新（HH:mm）&quot; without an exception box; ③ after restoring, it returns to the normal conclusion.</li></ul><hr><h2 id="_3-not-fixed-53-items-code-in-place-first-verification-of-these-the-app-side-of-b-103-b-104-b-502-was-fully-ci-unit-test-proxied-on-2026-10-13-patrol-b-and-checked-off-in-the-todo-mvp-issues-ledgers-—-this-chapter-keeps-the-corresponding-entries-only-as-installation-walkthrough-recheck-steps-count-rule-f2-rides-the-same-ledger-line-as-f1-and-is-not-counted-separately" tabindex="-1">3. Not fixed (53 items: code in place, first verification; of these, the app side of B-103/B-104/B-502 was fully CI/unit-test proxied on 2026-10-13 patrol-B and checked off in the todo/mvp-issues ledgers — this chapter keeps the corresponding entries only as installation walkthrough recheck steps. Count rule: F2 rides the same ledger line as F1 and is not counted separately) <a class="header-anchor" href="#_3-not-fixed-53-items-code-in-place-first-verification-of-these-the-app-side-of-b-103-b-104-b-502-was-fully-ci-unit-test-proxied-on-2026-10-13-patrol-b-and-checked-off-in-the-todo-mvp-issues-ledgers-—-this-chapter-keeps-the-corresponding-entries-only-as-installation-walkthrough-recheck-steps-count-rule-f2-rides-the-same-ledger-line-as-f1-and-is-not-counted-separately" aria-label="Permalink to &quot;3. Not fixed (53 items: code in place, first verification; of these, the app side of B-103/B-104/B-502 was fully CI/unit-test proxied on 2026-10-13 patrol-B and checked off in the todo/mvp-issues ledgers — this chapter keeps the corresponding entries only as installation walkthrough recheck steps. Count rule: F2 rides the same ledger line as F1 and is not counted separately)&quot;">​</a></h2><h3 id="a-installation-and-process" tabindex="-1">A Installation and process <a class="header-anchor" href="#a-installation-and-process" aria-label="Permalink to &quot;A Installation and process&quot;">​</a></h3><h4 id="a1-b-101-second-launch-does-not-duplicate-the-process" tabindex="-1">A1 | B-101 | Second launch does not duplicate the process <a class="header-anchor" href="#a1-b-101-second-launch-does-not-duplicate-the-process" aria-label="Permalink to &quot;A1 | B-101 | Second launch does not duplicate the process&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: Double-click the exe for a second launch.</li><li><strong>Expected</strong>: No second process appears; the existing instance is woken and shows a tip bubble.</li></ul><h4 id="a2-b-101-tray-residency" tabindex="-1">A2 | B-101 | Tray residency <a class="header-anchor" href="#a2-b-101-tray-residency" aria-label="Permalink to &quot;A2 | B-101 | Tray residency&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: Close all Beacon windows → look in Task Manager; then Exit from the tray menu.</li><li><strong>Expected</strong>: After closing windows the process stays in the tray; only Exit truly quits and the process disappears.</li></ul><h4 id="a3-批3-补271-tray-explorer-restart-recovery" tabindex="-1">A3 | 批3-补27① | Tray Explorer restart recovery <a class="header-anchor" href="#a3-批3-补271-tray-explorer-restart-recovery" aria-label="Permalink to &quot;A3 | 批3-补27① | Tray Explorer restart recovery&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, Beacon running.</li><li><strong>Steps</strong>: End and restart <code>explorer.exe</code> in Task Manager.</li><li><strong>Expected</strong>: After Explorer recovers, the tray icon comes back by itself and the severity color is not lost.</li></ul><h4 id="a4-批3-补272-sleep-wake-refresh-backfill" tabindex="-1">A4 | 批3-补27② | Sleep/wake refresh-backfill <a class="header-anchor" href="#a4-批3-补272-sleep-wake-refresh-backfill" aria-label="Permalink to &quot;A4 | 批3-补27② | Sleep/wake refresh-backfill&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, at least one widget.</li><li><strong>Steps</strong>: Sleep (or simulate with lock screen / network cut) → wake → observe the data update time.</li><li><strong>Expected</strong>: Within ≤1 refresh cycle after waking there is new data (does not depend on a manual force-refresh).</li></ul><h4 id="a5-批3-补28-capsule-right-click-goes-straight-to-settings" tabindex="-1">A5 | 批3-补28 | Capsule right-click goes straight to settings <a class="header-anchor" href="#a5-批3-补28-capsule-right-click-goes-straight-to-settings" aria-label="Permalink to &quot;A5 | 批3-补28 | Capsule right-click goes straight to settings&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: Right-click the capsule; then left-click-drag and left-click.</li><li><strong>Expected</strong>: Right-click pops the settings window; drag / click-to-open-panel behavior is not disturbed.</li></ul><h4 id="a6-b-104-launch-on-startup" tabindex="-1">A6 | B-104 | Launch on startup <a class="header-anchor" href="#a6-b-104-launch-on-startup" aria-label="Permalink to &quot;A6 | B-104 | Launch on startup&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: Turn on auto-start in settings → reboot; turn it off → reboot again; finally uninstall and check for leftovers.</li><li><strong>Expected</strong>: On → starts automatically after login; off → no longer auto-starts; no auto-start leftovers after uninstall.</li></ul><h4 id="a7-b-105-crash-fallback" tabindex="-1">A7 | B-105 | Crash fallback <a class="header-anchor" href="#a7-b-105-crash-fallback" aria-label="Permalink to &quot;A7 | B-105 | Crash fallback&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, E1.</li><li><strong>Steps</strong>: Manufacture an exception (e.g. point a config at an endpoint that throws) → observe the process and logs.</li><li><strong>Expected</strong>: The process survives, the logs contain a stack trace, no zombie windows.</li></ul><h4 id="a8-b-804-clean-vm-install" tabindex="-1">A8 | B-804 | Clean VM install <a class="header-anchor" href="#a8-b-804-clean-vm-install" aria-label="Permalink to &quot;A8 | B-804 | Clean VM install&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: A clean Windows 11 virtual machine.</li><li><strong>Steps</strong>: Download the nightly → run → complete the B-803 walkthrough (see <code>docs/acceptance-B803-e2e-walkthrough.md</code>).</li><li><strong>Expected</strong>: Installs, starts, the walkthrough passes.</li></ul><h4 id="a9-b-102-capsule-position-memory-no-mess-across-dpis" tabindex="-1">A9 | B-102 | Capsule position memory / no mess across DPIs <a class="header-anchor" href="#a9-b-102-capsule-position-memory-no-mess-across-dpis" aria-label="Permalink to &quot;A9 | B-102 | Capsule position memory / no mess across DPIs&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, C-DPI.</li><li><strong>Steps</strong>: ① drag the capsule to a non-default position → restart; ② drag across screens at different scales.</li><li><strong>Expected</strong>: After restart the capsule returns to its last position; dragging across DPIs has no size mess (mutual corroboration with 2.13/2.15).</li></ul><h4 id="a10-b-103-global-hotkey" tabindex="-1">A10 | B-103 | Global hotkey <a class="header-anchor" href="#a10-b-103-global-hotkey" aria-label="Permalink to &quot;A10 | B-103 | Global hotkey&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: ① press the hotkey while any foreground app is active (Notepad / browser / fullscreen games excepted); ② change the key in settings → restart → use the new key.</li><li><strong>Expected</strong>: The hotkey works in any foreground app and opens the panel; the changed key persists, the old key stops working and the new key works.</li></ul><h3 id="b-connections-and-widget-data-sources" tabindex="-1">B Connections and widget data sources <a class="header-anchor" href="#b-connections-and-widget-data-sources" aria-label="Permalink to &quot;B Connections and widget data sources&quot;">​</a></h3><h4 id="b1-批3-补31-jenkins-build-card" tabindex="-1">B1 | 批3-补31 | Jenkins build card <a class="header-anchor" href="#b1-批3-补31-jenkins-build-card" aria-label="Permalink to &quot;B1 | 批3-补31 | Jenkins build card&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, C-JENKINS.</li><li><strong>Steps</strong>: Create a Jenkins connection (anonymous or user:apiToken) → test → add a <code>jenkins.build</code> widget and fill in job_path.</li><li><strong>Expected</strong>: The build light / build number follows refreshes; building turns yellow; success green / failure red (color-based judgment).</li></ul><h4 id="b2-批3-补32-local-machine-network-card" tabindex="-1">B2 | 批3-补32 | Local machine network card <a class="header-anchor" href="#b2-批3-补32-local-machine-network-card" aria-label="Permalink to &quot;B2 | 批3-补32 | Local machine network card&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, C-MACHINE.</li><li><strong>Steps</strong>: Create a machine connection (zero credentials) → add a <code>machine.net</code> widget → refresh twice or more.</li><li><strong>Expected</strong>: IP and cumulative traffic are visible in L3; no rate on the first refresh, from the second refresh the ↓↑ rate changes with each refresh.</li></ul><h4 id="b3-批3-补33-local-machine-git-card" tabindex="-1">B3 | 批3-补33 | Local machine Git card <a class="header-anchor" href="#b3-批3-补33-local-machine-git-card" aria-label="Permalink to &quot;B3 | 批3-补33 | Local machine Git card&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, C-MACHINE, the path of any local Git repository.</li><li><strong>Steps</strong>: Add a <code>machine.git</code> widget with repo_path set to the local repository → refresh; then make the local branch fall behind the remote (e.g. revert a commit that exists on the remote).</li><li><strong>Expected</strong>: The ↑↓ / changed / stash counts follow refreshes; falling behind the remote turns yellow.</li></ul><h4 id="b4-批3-补36-local-machine-resource-card" tabindex="-1">B4 | 批3-补36 | Local machine resource card <a class="header-anchor" href="#b4-批3-补36-local-machine-resource-card" aria-label="Permalink to &quot;B4 | 批3-补36 | Local machine resource card&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, C-MACHINE.</li><li><strong>Steps</strong>: Add a <code>machine.local</code> widget → refresh continuously; lower the CPU threshold (e.g. to 20).</li><li><strong>Expected</strong>: CPU shows no value on the first refresh and the percentage follows refreshes from the second; memory / disk show instantaneous percentages; below the threshold, yellow judgment takes effect.</li></ul><h4 id="b5-批3-补34-mimo-whole-line-cookie" tabindex="-1">B5 | 批3-补34 | MiMo whole-line Cookie <a class="header-anchor" href="#b5-批3-补34-mimo-whole-line-cookie" aria-label="Permalink to &quot;B5 | 批3-补34 | MiMo whole-line Cookie&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, C-MIMO.</li><li><strong>Steps</strong>: Paste the whole Cookie line into the console credential box (not just the single api-platform_ph value) → refresh.</li><li><strong>Expected</strong>: Automatically extracts api-platform_ph and produces data (previously whole-line pasting left the card Offline).</li></ul><h4 id="b6-批3-补381-mimo-401-explicit-re-record-guidance" tabindex="-1">B6 | 批3-补38① | MiMo 401 explicit + re-record guidance <a class="header-anchor" href="#b6-批3-补381-mimo-401-explicit-re-record-guidance" aria-label="Permalink to &quot;B6 | 批3-补38① | MiMo 401 explicit + re-record guidance&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, C-MIMO.</li><li><strong>Steps</strong>: Deliberately enter an expired / scrambled console Cookie → refresh → look at the card&#39;s failure-reason line.</li><li><strong>Expected</strong>: The Degraded card explicitly states &quot;Cookie 已失效或未录制&quot; and gives the re-record guidance verbatim (including the F12 → api-platform_ph path).</li></ul><h4 id="b7-批3-补382-mimo-litellm-gateway-accounting-tier" tabindex="-1">B7 | 批3-补38② | MiMo LiteLLM gateway accounting tier <a class="header-anchor" href="#b7-批3-补382-mimo-litellm-gateway-accounting-tier" aria-label="Permalink to &quot;B7 | 批3-补38② | MiMo LiteLLM gateway accounting tier&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; the local LiteLLM gateway <strong>has a DB attached</strong> (the current <code>no_db_connection</code> is a gateway-side gap — this item is bound to the gateway-side fix; before a DB is attached only the explicit Degraded half is verified).</li><li><strong>Steps</strong>: Record <code>litellm_spend_url</code> in Settings (e.g. <code>http://127.0.0.1:4000/spend/logs</code>) → refresh.</li><li><strong>Expected</strong>: With a gateway DB the card shows &quot;本月已用 $X.XX（网关记账）&quot; (spent $X.XX this month (gateway accounting)); without a DB it explicitly shows the &quot;LiteLLM 未接数据库&quot; Degraded state, no silent downgrade.</li></ul><h4 id="b8-批3-补42-yaml-provider-dsl-end-to-end" tabindex="-1">B8 | 批3-补42 | YAML Provider DSL end-to-end <a class="header-anchor" href="#b8-批3-补42-yaml-provider-dsl-end-to-end" aria-label="Permalink to &quot;B8 | 批3-补42 | YAML Provider DSL end-to-end&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, C-HTTP; write a DSL file (see the &quot;Provider DSL&quot; section example in <code>docs/configuration.md</code>).</li><li><strong>Steps</strong>: ① set <code>dsl_path</code> in the http connection Settings to point at the declaration file → refresh an <code>http.status</code> widget (without filling data keys in widget.Config); ② fill the same-named keys in widget.Config and refresh again; ③ open that widget&#39;s detail page, look at the action area, and click an action with retry (make the target endpoint fail once first); ④ break the YAML (Tab indentation) and refresh again; ⑤ remove the file and refresh; ⑥ delete <code>dsl_path</code> and refresh.</li><li><strong>Expected</strong>: ① data comes out per the DSL mapping; ② instance values override the DSL; ③ DSL actions appear only on that connection&#39;s widgets, failures auto-retry, and a still-failing message carries &quot;已重试 N 次&quot; (retried N times); ④ the card goes Degraded with the line number explicit, startup is unaffected, other connections are normal; ⑤ likewise Degraded with &quot;文件不存在&quot; (file does not exist); ⑥ behavior is exactly the same as a connection that never used the DSL (zero change).</li></ul><h4 id="b9-b-206-offline-startup-has-data" tabindex="-1">B9 | B-206 | Offline startup has data <a class="header-anchor" href="#b9-b-206-offline-startup-has-data" aria-label="Permalink to &quot;B9 | B-206 | Offline startup has data&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, at least one widget that has produced data, C-DISCONNECT.</li><li><strong>Steps</strong>: Produce data normally once → exit → cut the network → start.</li><li><strong>Expected</strong>: The UI has cached data labeled Last update; after restoring the network it automatically refreshes new data (the cache hydration full-cycle unit test has passed; this item verifies the UI half).</li></ul><h4 id="b10-批3-补351-herald-incident-ledger-card" tabindex="-1">B10 | 批3-补35① | Herald incident ledger card <a class="header-anchor" href="#b10-批3-补351-herald-incident-ledger-card" aria-label="Permalink to &quot;B10 | 批3-补35① | Herald incident ledger card&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, C-HERALD.</li><li><strong>Steps</strong>: Create a herald connection → add a <code>herald.incidents</code> widget → manufacture / resolve one open incident on the herald side.</li><li><strong>Expected</strong>: The open count follows the ledger; open turns yellow, critical turns red; resolved turns green.</li></ul><h4 id="b11-批3-补352-herald-subscription-card" tabindex="-1">B11 | 批3-补35② | Herald subscription card <a class="header-anchor" href="#b11-批3-补352-herald-subscription-card" aria-label="Permalink to &quot;B11 | 批3-补35② | Herald subscription card&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, C-HERALD.</li><li><strong>Steps</strong>: Add a <code>herald.feed</code> widget (public category or private token) → wait for new entries to be delivered.</li><li><strong>Expected</strong>: The unread count of new entries increases with refreshes; the token goes to DPAPI and no plaintext lands anywhere.</li></ul><h4 id="b12-批3-补37-herald-delivery-failure-card" tabindex="-1">B12 | 批3-补37 | Herald delivery-failure card <a class="header-anchor" href="#b12-批3-补37-herald-delivery-failure-card" aria-label="Permalink to &quot;B12 | 批3-补37 | Herald delivery-failure card&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, C-HERALD.</li><li><strong>Steps</strong>: Add a <code>herald.deliveries</code> widget → manufacture one failed delivery (stop the target provider and then notify).</li><li><strong>Expected</strong>: Shows &quot;无失败&quot; (no failures) when there are none; turns yellow after a failure and shows the failure count.</li></ul><h4 id="b13-b-301-supplement-anonymous-connection-degradation-companion-item-verified-together-with-2-1-not-counted-in-the-53" tabindex="-1">B13 | B-301 supplement | Anonymous connection degradation (companion item, verified together with 2.1, not counted in the 53) <a class="header-anchor" href="#b13-b-301-supplement-anonymous-connection-degradation-companion-item-verified-together-with-2-1-not-counted-in-the-53" aria-label="Permalink to &quot;B13 | B-301 supplement | Anonymous connection degradation (companion item, verified together with 2.1, not counted in the 53)&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Same as 2.1.</li><li><strong>Steps</strong>: Create a GitHub connection without a PAT and observe the degradation behavior.</li><li><strong>Expected</strong>: Shows honestly per the anonymous limit, does not impersonate authenticated. (Overlaps with step ② of 2.1; can be verified together)</li></ul><h3 id="c-actions" tabindex="-1">C Actions <a class="header-anchor" href="#c-actions" aria-label="Permalink to &quot;C Actions&quot;">​</a></h3><h4 id="c1-b-401-action-failure-ui-feedback" tabindex="-1">C1 | B-401 | Action failure UI feedback <a class="header-anchor" href="#c1-b-401-action-failure-ui-feedback" aria-label="Permalink to &quot;C1 | B-401 | Action failure UI feedback&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; an action that will fail (e.g. a URL pointing at a dead port).</li><li><strong>Steps</strong>: Click that action on the detail page.</li><li><strong>Expected</strong>: The UI gives visible failure feedback (result text / color), does not go silent.</li></ul><h4 id="c2-b-402-open-url-in-browser" tabindex="-1">C2 | B-402 | Open URL in browser <a class="header-anchor" href="#c2-b-402-open-url-in-browser" aria-label="Permalink to &quot;C2 | B-402 | Open URL in browser&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; a widget with a DetailUrl.</li><li><strong>Steps</strong>: Click Open on the detail page.</li><li><strong>Expected</strong>: The default browser opens the correct URL (the template-rendering unit test has passed; this item verifies the browser half).</li></ul><h4 id="c3-b-403-workflow-dispatch-full-journey" tabindex="-1">C3 | B-403 | Workflow Dispatch full journey <a class="header-anchor" href="#c3-b-403-workflow-dispatch-full-journey" aria-label="Permalink to &quot;C3 | B-403 | Workflow Dispatch full journey&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0, C-GH, a repository with dispatch permission.</li><li><strong>Steps</strong>: Dispatch a workflow → observe the whole Run→running→terminal-state journey.</li><li><strong>Expected</strong>: The whole state journey is visible in Beacon (no need to open the GitHub web page).</li></ul><h4 id="c4-b-404-local-command-confirm-dialog-timeout-persistence" tabindex="-1">C4 | B-404 | Local command confirm dialog + timeout persistence <a class="header-anchor" href="#c4-b-404-local-command-confirm-dialog-timeout-persistence" aria-label="Permalink to &quot;C4 | B-404 | Local command confirm dialog + timeout persistence&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; configure a local.command action.</li><li><strong>Steps</strong>: ① trigger the action and look at the confirm dialog; ② configure a long command to verify timeout termination and log persistence.</li><li><strong>Expected</strong>: Confirm dialog by default (can be turned off per action config); the timeout kills the process and the output is still persisted to disk (the executor unit test has passed; this item verifies the dialog UI half).</li></ul><h3 id="d-notifications" tabindex="-1">D Notifications <a class="header-anchor" href="#d-notifications" aria-label="Permalink to &quot;D Notifications&quot;">​</a></h3><h4 id="d1-b-501-toast-full-chain" tabindex="-1">D1 | B-501 | Toast full chain <a class="header-anchor" href="#d1-b-501-toast-full-chain" aria-label="Permalink to &quot;D1 | B-501 | Toast full chain&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; a notification rule hits.</li><li><strong>Steps</strong>: ① trigger a Toast; ② click the Toast; ③ delete the AUMID registration key under HKCU\\Software\\Classes\\AppUserModelId (with CustomActivator) and restart the app to retry.</li><li><strong>Expected</strong>: Send / click / activation routing all work; missing AUMID registration self-heals (the toolkit Initialize rebuilds the registration key on next startup).</li></ul><h4 id="d2-b-502-toast-cooldown" tabindex="-1">D2 | B-502 | Toast cooldown <a class="header-anchor" href="#d2-b-502-toast-cooldown" aria-label="Permalink to &quot;D2 | B-502 | Toast cooldown&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; same as above.</li><li><strong>Steps</strong>: Inject a Failed state (e.g. point some connection at a bad endpoint to trigger Error).</li><li><strong>Expected</strong>: Exactly one Toast is received (no repeated bombardment inside the cooldown window).</li></ul><h4 id="d3-b-503-tray-coloring" tabindex="-1">D3 | B-503 | Tray coloring <a class="header-anchor" href="#d3-b-503-tray-coloring" aria-label="Permalink to &quot;D3 | B-503 | Tray coloring&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; controllable widget states.</li><li><strong>Steps</strong>: Manufacture Warning/Error → look at the tray icon.</li><li><strong>Expected</strong>: Aggregated state changes are reflected in the tray icon color within ≤1 refresh cycle.</li></ul><h4 id="d4-b-504-capsule-real-aggregation" tabindex="-1">D4 | B-504 | Capsule real aggregation <a class="header-anchor" href="#d4-b-504-capsule-real-aggregation" aria-label="Permalink to &quot;D4 | B-504 | Capsule real aggregation&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; controllable widget states.</li><li><strong>Steps</strong>: Cut the network (C-DISCONNECT) and look at the capsule; after restoring, verify the counts.</li><li><strong>Expected</strong>: Offline shows an Offline banner + time when the network is cut; the counts match the actual Widget states.</li></ul><h3 id="e-l2-l3" tabindex="-1">E L2 / L3 <a class="header-anchor" href="#e-l2-l3" aria-label="Permalink to &quot;E L2 / L3&quot;">​</a></h3><h4 id="e1-b-601-quick-panel-open-close" tabindex="-1">E1 | B-601 | Quick Panel open/close <a class="header-anchor" href="#e1-b-601-quick-panel-open-close" aria-label="Permalink to &quot;E1 | B-601 | Quick Panel open/close&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: Open the panel with the hotkey → close with Esc → click outside to close on focus loss; traverse fully with keyboard Tab/arrow keys and close; open and close repeatedly.</li><li><strong>Expected</strong>: Opens in &lt;100ms with no white screen (cache first); fully operable and closable by keyboard; repeated toggling is stable.</li></ul><h4 id="e2-b-602-overview-pin-persistence" tabindex="-1">E2 | B-602 | Overview/Pin persistence <a class="header-anchor" href="#e2-b-602-overview-pin-persistence" aria-label="Permalink to &quot;E2 | B-602 | Overview/Pin persistence&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: Compare the Overview counts with the actual states; right-click Pin one widget → restart.</li><li><strong>Expected</strong>: Counts / events are consistent; Pin persists (even without L0 UI effects in this phase it must land in widgets.json/pins.json).</li></ul><h4 id="e3-b-603-detail-retry-chain" tabindex="-1">E3 | B-603 | Detail + Retry chain <a class="header-anchor" href="#e3-b-603-detail-retry-chain" aria-label="Permalink to &quot;E3 | B-603 | Detail + Retry chain&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; a run with a failing job.</li><li><strong>Steps</strong>: Open the detail page in one click from an L2 event → click [Retry].</li><li><strong>Expected</strong>: The detail page goes straight to the corresponding object; the Retry full chain works (including confirmation and result feedback).</li></ul><h3 id="f-l0-tile-behavior" tabindex="-1">F L0 tile behavior <a class="header-anchor" href="#f-l0-tile-behavior" aria-label="Permalink to &quot;F L0 tile behavior&quot;">​</a></h3><h4 id="f1-b-7011-click-does-not-steal-focus" tabindex="-1">F1 | B-701① | Click does not steal focus <a class="header-anchor" href="#f1-b-7011-click-does-not-steal-focus" aria-label="Permalink to &quot;F1 | B-701① | Click does not steal focus&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; an L0 floating tile (settings toggle or Pin).</li><li><strong>Steps</strong>: Focus a foreground app (e.g. Notepad) → click the tile.</li><li><strong>Expected</strong>: The foreground app&#39;s focus is not stolen (you can keep typing).</li></ul><h4 id="f2-b-7011b-blank-click-falls-through-to-the-desktop-same-ledger-line-as-f1" tabindex="-1">F2 | B-701①b | Blank click falls through to the desktop (same ledger line as F1) <a class="header-anchor" href="#f2-b-7011b-blank-click-falls-through-to-the-desktop-same-ledger-line-as-f1" aria-label="Permalink to &quot;F2 | B-701①b | Blank click falls through to the desktop (same ledger line as F1)&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Same as F1.</li><li><strong>Steps</strong>: Click the blank area of the tile window.</li><li><strong>Expected</strong>: The click passes through to the desktop (the tile does not eat clicks).</li></ul><h4 id="f3-b-7012-two-tiles-update-independently" tabindex="-1">F3 | B-701② | Two tiles update independently <a class="header-anchor" href="#f3-b-7012-two-tiles-update-independently" aria-label="Permalink to &quot;F3 | B-701② | Two tiles update independently&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Tiles of two different-source widgets.</li><li><strong>Steps</strong>: Change only one source&#39;s state.</li><li><strong>Expected</strong>: The two tiles update independently of each other; the windows do not enter the taskbar / Alt-Tab.</li></ul><h4 id="f4-b-7012b-floating-form-drag-placement-restore" tabindex="-1">F4 | B-701②b | Floating-form drag placement restore <a class="header-anchor" href="#f4-b-7012b-floating-form-drag-placement-restore" aria-label="Permalink to &quot;F4 | B-701②b | Floating-form drag placement restore&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Floating form enabled.</li><li><strong>Steps</strong>: Drag a tile → restart.</li><li><strong>Expected</strong>: One window per widget is draggable; positions are restored after restart; mutually exclusive with the host panel (either/or).</li></ul><h4 id="f5-b-7021-pin-dual-entry-consistency" tabindex="-1">F5 | B-702① | Pin dual-entry consistency <a class="header-anchor" href="#f5-b-7021-pin-dual-entry-consistency" aria-label="Permalink to &quot;F5 | B-702① | Pin dual-entry consistency&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: Pin / unpin the same widget via the settings toggle and the context menu respectively.</li><li><strong>Expected</strong>: Both entries behave identically and persist.</li></ul><h4 id="f6-b-7022-non-admitted-types-cannot-be-pinned" tabindex="-1">F6 | B-702② | Non-admitted types cannot be pinned <a class="header-anchor" href="#f6-b-7022-non-admitted-types-cannot-be-pinned" aria-label="Permalink to &quot;F6 | B-702② | Non-admitted types cannot be pinned&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: Try pinning a non-PinSupported type (e.g. a claude.usage-class local card) in both entries.</li><li><strong>Expected</strong>: Both entries refuse to pin (the policy unit test has passed; this item verifies the UI gating).</li></ul><h4 id="f7-b-7031-position-collapsed-state-restore-monitor-unplug" tabindex="-1">F7 | B-703① | Position / collapsed-state restore + monitor unplug <a class="header-anchor" href="#f7-b-7031-position-collapsed-state-restore-monitor-unplug" aria-label="Permalink to &quot;F7 | B-703① | Position / collapsed-state restore + monitor unplug&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Two or more L0 tiles.</li><li><strong>Steps</strong>: Drag positions, collapse → restart; then unplug the monitor where a tile lives → plug it back.</li><li><strong>Expected</strong>: After restart, positions / collapsed states are restored; after unplug/plug the tile is not lost (recycled or returned to a visible area).</li></ul><h4 id="f8-b-7032-cross-dpi-dragging-and-recycling" tabindex="-1">F8 | B-703② | Cross-DPI dragging and recycling <a class="header-anchor" href="#f8-b-7032-cross-dpi-dragging-and-recycling" aria-label="Permalink to &quot;F8 | B-703② | Cross-DPI dragging and recycling&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: C-DPI multiple monitors.</li><li><strong>Steps</strong>: Drag a tile across DPI-different monitors; shrink the secondary monitor&#39;s resolution.</li><li><strong>Expected</strong>: Dragging sizes are correct (DpiLayoutMath as the single source of truth); after shrinking the resolution the tile is recycled into a visible area.</li></ul><h4 id="f9-b-704-offline-self-healing" tabindex="-1">F9 | B-704 | Offline self-healing <a class="header-anchor" href="#f9-b-704-offline-self-healing" aria-label="Permalink to &quot;F9 | B-704 | Offline self-healing&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: L0 tile; C-DISCONNECT.</li><li><strong>Steps</strong>: Cut the network and observe the whole flow → restore.</li><li><strong>Expected</strong>: No popup windows at any point (Offline state only); after restoring the tile self-heals with new data (the socket-level integration test has passed; this item verifies the UI half).</li></ul><h4 id="f10-b-7051-critical-only-pulses" tabindex="-1">F10 | B-705① | Critical only pulses <a class="header-anchor" href="#f10-b-7051-critical-only-pulses" aria-label="Permalink to &quot;F10 | B-705① | Critical only pulses&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; inject Critical (drag the threshold to an extreme or manufacture an Error+ state).</li><li><strong>Steps</strong>: Observe L0 after injecting.</li><li><strong>Expected</strong>: L0 only changes color and pulses, no interruption (no popup, no focus stealing); the Toast is still emitted by the notification engine as usual.</li></ul><h4 id="f11-b-7052-rfc-§6-2-7-four-item-checklist" tabindex="-1">F11 | B-705② | RFC §6.2.7 four-item checklist <a class="header-anchor" href="#f11-b-7052-rfc-§6-2-7-four-item-checklist" aria-label="Permalink to &quot;F11 | B-705② | RFC §6.2.7 four-item checklist&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Same as F10.</li><li><strong>Steps</strong>: Execute the four-item checklist in <code>docs/acceptance-B705-L0-behavior.md</code> item by item and record.</li><li><strong>Expected</strong>: All four items pass with records kept.</li></ul><h3 id="g-appearance-and-motion" tabindex="-1">G Appearance and motion <a class="header-anchor" href="#g-appearance-and-motion" aria-label="Permalink to &quot;G Appearance and motion&quot;">​</a></h3><h4 id="g1-b-7061-severity-colors-sync-across-three-surfaces" tabindex="-1">G1 | B-706① | Severity colors sync across three surfaces <a class="header-anchor" href="#g1-b-7061-severity-colors-sync-across-three-surfaces" aria-label="Permalink to &quot;G1 | B-706① | Severity colors sync across three surfaces&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; L0 tile + capsule + tray all visible at once.</li><li><strong>Steps</strong>: Change a severity color in settings (e.g. Warning to orange).</li><li><strong>Expected</strong>: The L0 tile, capsule, and tray icon all change color in sync.</li></ul><h4 id="g2-b-7062-coloroverride-single-tile" tabindex="-1">G2 | B-706② | colorOverride single tile <a class="header-anchor" href="#g2-b-7062-coloroverride-single-tile" aria-label="Permalink to &quot;G2 | B-706② | colorOverride single tile&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Two or more tiles.</li><li><strong>Steps</strong>: Set colorOverride on one Widget only.</li><li><strong>Expected</strong>: Only that tile changes color; priority Widget &gt; severity &gt; default is correct.</li></ul><h4 id="g3-b-7063-illegal-color-fallback" tabindex="-1">G3 | B-706③ | Illegal color fallback <a class="header-anchor" href="#g3-b-7063-illegal-color-fallback" aria-label="Permalink to &quot;G3 | B-706③ | Illegal color fallback&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Same as G2.</li><li><strong>Steps</strong>: Enter an illegal color value (e.g. <code>#GGG</code>) → restart.</li><li><strong>Expected</strong>: Falls back to the default color without crashing; keeps the fallback state after restart.</li></ul><h4 id="g4-b-7071-color-change-transition" tabindex="-1">G4 | B-707① | Color-change transition <a class="header-anchor" href="#g4-b-7071-color-change-transition" aria-label="Permalink to &quot;G4 | B-707① | Color-change transition&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Motion tier reduced.</li><li><strong>Steps</strong>: Manufacture a Success→Error change.</li><li><strong>Expected</strong>: Smooth color-change transition (not an instant jump).</li></ul><h4 id="g5-b-7072-critical-pulse-three-tiers" tabindex="-1">G5 | B-707② | Critical pulse three tiers <a class="header-anchor" href="#g5-b-7072-critical-pulse-three-tiers" aria-label="Permalink to &quot;G5 | B-707② | Critical pulse three tiers&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Motion settings page.</li><li><strong>Steps</strong>: Look at the pulse on the default tier; look at full stillness on the off tier; look at the breathing light on the full tier and adjust intensity.</li><li><strong>Expected</strong>: Pulse on by default; off is fully still; full shows a visible breathing light and the intensity is adjustable.</li></ul><h4 id="g6-b-7073-motion-boundaries" tabindex="-1">G6 | B-707③ | Motion boundaries <a class="header-anchor" href="#g6-b-7073-motion-boundaries" aria-label="Permalink to &quot;G6 | B-707③ | Motion boundaries&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Motion enabled.</li><li><strong>Steps</strong>: Listen for sound / try to steal focus during motion; after hiding / collapsing the tile, check power draw (Task Manager CPU/GPU).</li><li><strong>Expected</strong>: No focus stealing, no sound; no animation loop while hidden / collapsed (power draw falls back).</li></ul><h3 id="h-import-export-and-settings" tabindex="-1">H Import/export and settings <a class="header-anchor" href="#h-import-export-and-settings" aria-label="Permalink to &quot;H Import/export and settings&quot;">​</a></h3><h4 id="h1-b-802-import-export-end-to-end" tabindex="-1">H1 | B-802 | Import/export end-to-end <a class="header-anchor" href="#h1-b-802-import-export-end-to-end" aria-label="Permalink to &quot;H1 | B-802 | Import/export end-to-end&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0; an instance with credentials configured.</li><li><strong>Steps</strong>: Export → search the whole file for tokens; import in another directory (or VM) → re-enter secrets → compare behavior.</li><li><strong>Expected</strong>: The exported file contains no token anywhere (JSON stores only credentialRef, secrets are not packaged); after import + re-entry the behavior matches the original machine (the storage layer&#39;s 5 tests have passed; this item verifies the end-to-end half).</li></ul><h4 id="h2-b-8051-palette-motion-live-preview-persistence" tabindex="-1">H2 | B-805① | Palette / motion live preview persistence <a class="header-anchor" href="#h2-b-8051-palette-motion-live-preview-persistence" aria-label="Permalink to &quot;H2 | B-805① | Palette / motion live preview persistence&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: Change color / change tier → look at the live preview → restart.</li><li><strong>Expected</strong>: Changes take effect immediately and persist, still there after restart.</li></ul><h4 id="h3-b-8052-reset-defaults-off-tier" tabindex="-1">H3 | B-805② | Reset defaults + off tier <a class="header-anchor" href="#h3-b-8052-reset-defaults-off-tier" aria-label="Permalink to &quot;H3 | B-805② | Reset defaults + off tier&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Same as H2.</li><li><strong>Steps</strong>: Click reset defaults; select the off tier and look at the preview.</li><li><strong>Expected</strong>: One-click restore of defaults; the off tier preview is fully still.</li></ul><h3 id="i-final-acceptance" tabindex="-1">I Final acceptance <a class="header-anchor" href="#i-final-acceptance" aria-label="Permalink to &quot;I Final acceptance&quot;">​</a></h3><h4 id="i1-b-803-mvp-full-journey-walkthrough" tabindex="-1">I1 | B-803 | MVP full-journey walkthrough <a class="header-anchor" href="#i1-b-803-mvp-full-journey-walkthrough" aria-label="Permalink to &quot;I1 | B-803 | MVP full-journey walkthrough&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: Everything above (or key samples) passed.</li><li><strong>Steps</strong>: Record screenshots / a recording per the task-book §success criteria, archive under <code>docs/</code> (the walkthrough script is in <code>docs/acceptance-B803-e2e-walkthrough.md</code>).</li><li><strong>Expected</strong>: Full recording archived; all found problems fixed or filed as Issues.</li></ul><h4 id="i2-sha256-and-timestamp-cross-check-companion-item-not-counted-in-the-53" tabindex="-1">I2 | SHA256 and timestamp cross-check (companion item, not counted in the 53) <a class="header-anchor" href="#i2-sha256-and-timestamp-cross-check-companion-item-not-counted-in-the-53" aria-label="Permalink to &quot;I2 | SHA256 and timestamp cross-check (companion item, not counted in the 53)&quot;">​</a></h4><ul><li><strong>Preconditions</strong>: E0.</li><li><strong>Steps</strong>: Compare the download-page hash with the local zip.</li><li><strong>Expected</strong>: Consistent (the release assertion has been verified; this item is the installation-side recheck).</li></ul><hr><h2 id="appendix-local-automation-coverage-notes-2026-10-10-triage-commit-4b04205-批3-补39-42-45-47-48-49-additions-currently-991-991-green" tabindex="-1">Appendix: local automation coverage notes (2026-10-10 triage commit 4b04205 + 批3-补39/42/45/47/48/49 additions, currently 991/991 green) <a class="header-anchor" href="#appendix-local-automation-coverage-notes-2026-10-10-triage-commit-4b04205-批3-补39-42-45-47-48-49-additions-currently-991-991-green" aria-label="Permalink to &quot;Appendix: local automation coverage notes (2026-10-10 triage commit 4b04205 + 批3-补39/42/45/47/48/49 additions, currently 991/991 green)&quot;">​</a></h2><p>Windows runtime behavior is governed by the installation walkthrough in this checklist; the following records what has already been proven locally, to avoid repeated troubleshooting when receipting:</p><ul><li><strong>Two items already checked (fully proven by local automation)</strong>: <ul><li>B-801: SerializationRoundTripTests (AppConfig full-field round-trip + defaults invariant) + JsonConfigurationStoreTests.AppConfig_AllFields_SurviveSaveAndReload (startup path field-by-field comparison) + the token-does-not-land-in-JSON unit tests (DpapiSecretStore/ImportExport).</li><li>B-207: OutageRecoveryIntegrationTests — real HttpClient connection refused→Offline+stale state (old cache kept); recovery auto-resets; RefreshWidgetAsync returns false without throwing; first failure with no cache shows &quot;拉取失败&quot; directly.</li></ul></li><li><strong>Local halves of unchecked items (UI/interaction halves need a real machine, keep them on the ledger without proxy verification)</strong>: <ul><li>B-706×3: PaletteResolverTests (priority Widget&gt;severity&gt;default / illegal value fallback / offline key) — color linkage and persistence UI half pending a real machine.</li><li>B-702 second item: WidgetDisplayPolicyTests.PanelCarries_NonPinSupported_NeverCarried — both entries&#39; interaction pending a real machine.</li><li>B-703 geometry: PinLayoutMathTests (anchor / DPI / out-of-bounds recycling / topology judgment) — dragging and monitor unplug/plug pending a real machine.</li><li>B-207 branch supplement: WidgetHostTests fake Handler (Degraded / backoff / healthy de-duplication).</li><li>B-301/B-302/B-303: GitHubApiClient/GitHubPullRequests/GitHubActions fake Handler full branches (批3-补14/15) — real credentials and real repository halves pending a real machine.</li><li>B-401/B-404: ActionRunnerTests 15 tests (routing/confirm/timeout/cancel/retry six states) + LocalCommandExecutorTests (timeout kills process + persistence) — dialog and feedback UI halves pending a real machine.</li><li>批3-补42 DSL: ProviderDslTests 46 tests (parse/validate/cache/MappingValue/end-to-end) + ActionRunner retry 6 tests — real-machine dsl_path configuration and action-click halves pending.</li><li>批3-补47 update check: UpdateCheckTests 48 tests (version parsing shapes and rejection table, SemVer 12 comparison groups including pre-release rules, Evaluate including nightly date conventions, rate-limit degradation) — the GitHub real-endpoint half (three-line display, button semantics, offline degradation) pending a real machine.</li><li>批3-补48 tile text-width budget + multi-window quota: TileSizingTests 32 tests (text-width model per type / per-type worst-row → total width / label priority aligned to PinTile / machine show linkage) + WidgetValueHintTests multi-window 8 tests (three-window / two-window / out-of-order / remaining convention / single-window not entering / readout collapse judgment) — the visual half that the floating panel&#39;s numeric column no longer clips text pending the installation walkthrough.</li></ul></li></ul>',171)])])}const p=t(n,[["render",r]]);export{g as __pageData,p as default};
